package io.github.jesterportfolio.hearth.verification;

import io.github.jesterportfolio.hearth.economy.*;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.inventory.*;
import io.github.jesterportfolio.hearth.session.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.bukkit.*;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;
import org.postgresql.ds.PGSimpleDataSource;

/** 새 소유 시험의 경제 직접 거래. Player 생성/인증 우회·실제 클릭 대체를 하지 않습니다. */
public final class PeerTradeVerification {
    private static final UUID A=new UUID(0x45434f,601),B=new UUID(0x45434f,602),C=new UUID(0x45434f,701),D=new UUID(0x45434f,702),RAW=new UUID(0x45434f,301),OLD=new UUID(0x45434f,302),RECEIPT=new UUID(0x45434f,501),UNKNOWN=new UUID(0x45434f,599);
    private PeerTradeVerification(){}
    private static Path root(JavaPlugin plugin)throws Exception{if(!Boolean.getBoolean("hearth.verification.peerTrade")||!Bukkit.getOnlinePlayers().isEmpty())throw new IllegalStateException("PEER_PROBE_GATE");var root=IsolatedPaths.require(Path.of("").toRealPath().getParent(),"hearth-s4-11.");if(!Files.readString(root.resolve(".hearth-lifecycle-isolated")).equals("S4-11 isolated test only\n")||!plugin.getDataFolder().toPath().toRealPath().equals(root.resolve("server/plugins/Hearth")))throw new IllegalStateException("PEER_PROBE_GATE");return root;}
    private static void check(JavaPlugin plugin,boolean ok,String label){if(!ok)throw new IllegalStateException("PEER_CHECK_FAILED_"+label);plugin.getLogger().info("HEARTH_SESSION_CHECK PASS peer_trade_"+label);}
    private static <T> CompletionStage<T> on(CompletionStage<T> work,Executor owner){return work.thenApplyAsync(v->v,owner);}
    private static CompletionStage<Void> reject(CompletionStage<?> work,String code,JavaPlugin plugin,String label,Executor owner){return work.handleAsync((v,error)->{check(plugin,error!=null&&InventorySaveSession.code(error).equals(code),label);return (Void)null;},owner);}
    private static String account(EconomyStore.Account value){return value.balance()+"/"+value.inventory().revision()+"/"+Base64.getEncoder().encodeToString(value.inventory().payload().bytes());}
    private static InventoryPayload items(PaperInventoryCodec codec,boolean ore){var items=new ItemStack[41];items[0]=new ItemStack(ore?Material.IRON_ORE:Material.IRON_INGOT,10);items[36]=new ItemStack(Material.IRON_BOOTS);items[40]=new ItemStack(Material.SHIELD);return codec.encode(items);}
    private static CompletionStage<PlayerSessions.Session> connect(PaperEconomy economy,ServerProgressAccess.Context context,Executor owner){var actor=new PlayerSessions.Port(){InventoryPayload value;public boolean connected(){return true;}public InventoryPayload capture(){return value;}public void apply(InventoryPayload payload){value=payload;}public CompletionStage<Boolean> move(){return CompletableFuture.completedFuture(true);}};var s=economy.sessions.connect(context,economy.world,actor);return on(s.ready(),owner).thenApply(v->s);}
    private static CompletionStage<Void> legacy(PostgresProgressStore db,PaperEconomy economy,PaperInventoryCodec codec){var legacyPayload=items(codec,true).bytes();return db.module("peer_fixture_legacy",c->{
        try(var st=c.createStatement();var r=st.executeQuery("SELECT to_regnamespace('hearth_economy')")){r.next();if(r.getObject(1)!=null)throw new IllegalStateException("PEER_FIXTURE_NOT_FRESH");}
        for(int version=1;version<=3;version++){String name=List.of("E001__economy.sql","E002__trade_history.sql","E003__tick_flow.sql").get(version-1);byte[] bytes;try(var input=PeerTradeVerification.class.getResourceAsStream("/db/economy/"+name)){bytes=Objects.requireNonNull(input).readAllBytes();}try(var st=c.createStatement()){st.execute(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));}String hash=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));try(var st=c.prepareStatement("INSERT INTO hearth_economy.version VALUES (?,?)")){st.setInt(1,version);st.setString(2,hash);st.executeUpdate();}}
        try(var st=c.prepareStatement("INSERT INTO hearth_economy.realm VALUES (?,?,0,0,0,NULL)")){st.setObject(1,OLD);st.setString(2,economy.store.content().fingerprint());st.executeUpdate();}try(var st=c.prepareStatement("INSERT INTO hearth_economy.account VALUES (?,?,123,?,7)")){st.setObject(1,OLD);st.setObject(2,A);st.setBytes(3,legacyPayload);st.executeUpdate();}return null;
    });}
    public static CompletionStage<Void> prepare(JavaPlugin plugin,PostgresProgressStore db,PaperEconomy economy,PaperInventoryCodec codec,Executor owner){
        final Path root;try{root=root(plugin);}catch(Exception error){return CompletableFuture.failedFuture(error);}var expected=new Properties();var left=economy.store.context(economy.realm,A);var right=economy.store.context(economy.realm,B);var sessions=new PlayerSessions.Session[2];
        return on(db.module("peer_story_before",EconomyRuntimeVerification::progress),owner).thenAccept(hash->expected.setProperty("story",hash))
            .thenCompose(v->on(legacy(db,economy,codec),owner)).thenCompose(v->on(economy.store.migrate(),owner))
            .thenCompose(v->on(economy.store.account(economy.store.context(OLD,A)),owner)).thenAccept(row->check(plugin,row.balance()==123&&row.inventory().revision()==7&&row.inventory().payload().equals(items(codec,true)),"E003_upgrade_preserves_legacy_account_and_original_migration_checksums"))
            .thenCompose(v->on(economy.store.createRealm(economy.realm,System.currentTimeMillis()),owner)).thenCompose(v->on(economy.store.createAccount(left,1000,items(codec,true)),owner)).thenCompose(v->on(economy.store.createAccount(right,1000,items(codec,false)),owner))
            .thenCompose(v->raw(plugin,db,economy,codec,owner))
            .thenCompose(v->connect(economy,left,owner)).thenAccept(s->sessions[0]=s).thenCompose(v->connect(economy,right,owner)).thenAccept(s->sessions[1]=s)
            .thenCompose(v->{var deal=new PeerTrade(RECEIPT,economy.realm,A,B);deal.accept(B);deal.edit(A,new PeerTrade.Offer(Map.of("iron_ore",3),50));deal.edit(B,new PeerTrade.Offer(Map.of("iron_ingot",1),10));check(plugin,!deal.confirm(A,deal.revision())&&deal.confirm(B,deal.revision()),"bilateral_latest_revision_required_before_session_transaction");return on(economy.peers.exchange.execute(economy.sessions,sessions[0],sessions[1],deal,()->true,EconomyStore.Probe.NONE),owner);})
            .thenAccept(result->check(plugin,result.first().balance()==960&&result.second().balance()==1040&&result.first().inventory().revision()==1&&result.second().inventory().revision()==1,"both_latest_session_inventories_and_money_committed_once"))
            .thenCompose(v->on(economy.store.account(left),owner)).thenAccept(row->expected.setProperty("a",account(row))).thenCompose(v->on(economy.store.account(right),owner)).thenAccept(row->expected.setProperty("b",account(row)))
            .thenCompose(v->on(economy.sessions.disconnect(sessions[0]),owner)).thenCompose(v->on(economy.sessions.disconnect(sessions[1]),owner))
            .thenCompose(v->on(db.module("peer_story_after",EconomyRuntimeVerification::progress),owner)).thenAccept(hash->check(plugin,hash.equals(expected.getProperty("story")),"economic_migration_trade_and_failure_cases_preserve_all_story_tables"))
            .thenRunAsync(()->{try(var output=Files.newOutputStream(root.resolve("peer-trade-expected.properties"),StandardOpenOption.CREATE_NEW)){expected.store(output,"Synthetic PG/currency/item conservation and restore inputs only");}catch(Exception error){throw new CompletionException(error);}},owner);
    }
    private record Pair(EconomyStore.Account first,EconomyStore.Account second){}
    private static CompletionStage<Pair> pair(EconomyStore store,ServerProgressAccess.Context first,ServerProgressAccess.Context second,Executor owner){return on(store.account(first).thenCombine(store.account(second),Pair::new),owner);}
    private static EconomyStore.PeerRequest request(EconomyStore store,UUID realm,UUID id){return new EconomyStore.PeerRequest(id,store.context(realm,C),store.context(realm,D),new PeerTrade.Offer(Map.of("iron_ore",1),7),new PeerTrade.Offer(Map.of("iron_ingot",1),2));}
    private static CompletionStage<EconomyStore.PeerResult> execute(PaperEconomy economy,EconomyStore.PeerRequest request,Pair before,java.util.function.BooleanSupplier valid,EconomyStore.Probe probe){var a=economy.trades.change(economy.trades.change(before.first().inventory().payload(),"iron_ore",1,false),"iron_ingot",1,true);var b=economy.trades.change(economy.trades.change(before.second().inventory().payload(),"iron_ingot",1,false),"iron_ore",1,true);return economy.store.peer(request,before.first().inventory(),before.second().inventory(),a,b,valid,probe);}
    private static CompletionStage<Void> raw(JavaPlugin plugin,PostgresProgressStore db,PaperEconomy economy,PaperInventoryCodec codec,Executor owner){
        var store=economy.store;var a=store.context(RAW,C);var b=store.context(RAW,D);var before=new Pair[1];var current=new Pair[1];var request=request(store,RAW,new UUID(0x45434f,511));
        return on(store.createRealm(RAW,System.currentTimeMillis()),owner).thenCompose(v->on(store.createAccount(a,1000,items(codec,true)),owner)).thenCompose(v->on(store.createAccount(b,1000,items(codec,false)),owner)).thenCompose(v->pair(store,a,b,owner)).thenAccept(pair->before[0]=pair)
            .thenCompose(v->reject(execute(economy,request,before[0],()->true,EconomyStore.Probe.ROLLBACK),"23514",plugin,"injected_PG_failure_rolls_back_both_accounts_and_receipt",owner))
            .thenCompose(v->pair(store,a,b,owner)).thenAccept(pair->check(plugin,pair.equals(before[0]),"rollback_keeps_exact_two_account_originals"))
            .thenCompose(v->on(db.module("peer_fixture_trigger",c->{try(var st=c.createStatement()){st.execute("CREATE FUNCTION hearth_economy.reject_peer_second() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.player_uuid='"+D+"'::uuid THEN RAISE EXCEPTION 'isolated second account failure' USING ERRCODE='23514'; END IF; RETURN NEW; END $$");st.execute("CREATE TRIGGER reject_peer_second BEFORE UPDATE ON hearth_economy.account FOR EACH ROW EXECUTE FUNCTION hearth_economy.reject_peer_second()");}return null;}),owner))
            .thenCompose(v->reject(execute(economy,request(store,RAW,new UUID(0x45434f,512)),before[0],()->true,EconomyStore.Probe.NONE),"23514",plugin,"real_second_account_SQL_failure_rolls_back_first_account",owner))
            .thenCompose(v->on(db.module("peer_fixture_trigger_remove",c->{try(var st=c.createStatement()){st.execute("DROP TRIGGER reject_peer_second ON hearth_economy.account");st.execute("DROP FUNCTION hearth_economy.reject_peer_second()");}return null;}),owner))
            .thenCompose(v->pair(store,a,b,owner)).thenAccept(pair->check(plugin,pair.equals(before[0]),"second_account_failure_preserves_both_payloads_balances_revisions"))
            .thenCompose(v->{var stale=new Pair(new EconomyStore.Account(1000,new InventoryStore.Stored(before[0].first().inventory().payload(),1)),before[0].second());return reject(execute(economy,request(store,RAW,new UUID(0x45434f,513)),stale,()->true,EconomyStore.Probe.NONE),"CAS_CONFLICT",plugin,"stale_inventory_revision_rejected_without_debit",owner);})
            .thenCompose(v->{var calls=new AtomicInteger();return reject(execute(economy,request(store,RAW,new UUID(0x45434f,514)),before[0],()->calls.incrementAndGet()==1,EconomyStore.Probe.NONE),"STALE_CONTEXT",plugin,"late_fence_change_rolls_back_both_updates_and_receipt",owner);})
            .thenCompose(v->{var req=request(store,RAW,new UUID(0x45434f,515));return on(execute(economy,req,before[0],()->true,EconomyStore.Probe.NONE).thenCombine(execute(economy,req,before[0],()->true,EconomyStore.Probe.NONE),(one,two)->one.replay()!=two.replay()&&one.receipt().equals(two.receipt())),owner);}).thenAccept(ok->check(plugin,ok,"concurrent_identical_request_commits_once_and_returns_same_receipt"))
            .thenCompose(v->pair(store,a,b,owner)).thenAccept(pair->current[0]=pair)
            .thenCompose(v->{var one=request(store,RAW,new UUID(0x45434f,516));var two=request(store,RAW,new UUID(0x45434f,517));return on(execute(economy,one,current[0],()->true,EconomyStore.Probe.NONE).handle((r,e)->e==null?"OK":InventorySaveSession.code(e)).thenCombine(execute(economy,two,current[0],()->true,EconomyStore.Probe.NONE).handle((r,e)->e==null?"OK":InventorySaveSession.code(e)),(x,y)->x.equals("OK")&&y.equals("CAS_CONFLICT")||y.equals("OK")&&x.equals("CAS_CONFLICT")),owner);}).thenAccept(ok->check(plugin,ok,"concurrent_distinct_requests_have_one_CAS_winner"))
            .thenCompose(v->pair(store,a,b,owner)).thenAccept(pair->current[0]=pair)
            .thenCompose(v->{var changed=new EconomyStore.PeerRequest(new UUID(0x45434f,515),a,b,new PeerTrade.Offer(Map.of("iron_ore",2),7),new PeerTrade.Offer(Map.of("iron_ingot",1),2));return reject(execute(economy,changed,current[0],()->true,EconomyStore.Probe.NONE),"ECON_REQUEST_CONFLICT",plugin,"same_request_id_with_changed_offer_is_refused",owner);})
            .thenCompose(v->{var poor=new EconomyStore.PeerRequest(new UUID(0x45434f,518),a,b,new PeerTrade.Offer(Map.of("iron_ore",1),Long.MAX_VALUE),new PeerTrade.Offer(Map.of("iron_ingot",1),2));return reject(execute(economy,poor,current[0],()->true,EconomyStore.Probe.NONE),"ECON_FUNDS",plugin,"insufficient_funds_do_not_partially_transfer_goods",owner);})
            .thenCompose(v->on(store.offer(a,new EconomyContent.Key("mine","iron_ore")),owner)).thenCompose(offer->{var peer=request(store,RAW,new UUID(0x45434f,519));var npc=new EconomyStore.Request(a,new UUID(0x45434f,520),offer.key(),1,true,offer.market().revision());var after=economy.trades.change(current[0].first().inventory().payload(),"iron_ore",1,true);return on(execute(economy,peer,current[0],()->true,EconomyStore.Probe.NONE).handle((r,e)->e==null?"OK":InventorySaveSession.code(e)).thenCombine(store.trade(npc,current[0].first().inventory(),after,()->true,EconomyStore.Probe.NONE).handle((r,e)->e==null?"OK":InventorySaveSession.code(e)),(x,y)->x.equals("OK")&&y.equals("CAS_CONFLICT")||y.equals("OK")&&x.equals("CAS_CONFLICT")),owner);}).thenAccept(ok->check(plugin,ok,"NPC_and_peer_trade_share_CAS_and_cannot_spend_same_inventory_twice"))
            .thenCompose(v->pair(store,a,b,owner)).thenAccept(pair->current[0]=pair)
            .thenCompose(v->reject(execute(economy,request(store,RAW,UNKNOWN),current[0],()->true,EconomyStore.Probe.COMMIT_UNKNOWN),"COMMIT_UNKNOWN",plugin,"commit_unknown_does_not_claim_rollback_or_resubmit",owner))
            .thenCompose(v->on(store.peerReceipt(a,UNKNOWN),owner)).thenAccept(row->check(plugin,row.isPresent()&&row.get().firstRevision()==current[0].first().inventory().revision()+1&&row.get().secondRevision()==current[0].second().inventory().revision()+1,"unknown_commit_has_one_readable_durable_receipt"))
            .thenCompose(v->reject(store.peerReceipt(store.context(RAW,A),UNKNOWN),"ECON_REQUEST_CONFLICT",plugin,"third_party_cannot_read_peer_receipt",owner))
            .thenCompose(v->reject(store.peerReceipt(new ServerProgressAccess().forVerifiedServerLink(RAW,C),UNKNOWN),"ACCESS_DENIED",plugin,"foreign_issuer_cannot_read_economic_peer_data",owner));
    }
    public static CompletionStage<Void> restored(JavaPlugin plugin,EconomyRuntime runtime){
        final Path root;final Properties expected=new Properties();try{root=root(plugin);try(var input=Files.newInputStream(root.resolve("peer-trade-expected.properties"))){expected.load(input);}}catch(Exception e){return CompletableFuture.failedFuture(e);}var economy=runtime.economy();var owner=runtime.owner();var a=economy.store.context(economy.realm,A);var b=economy.store.context(economy.realm,B);
        check(plugin,runtime.phase()==EconomyRuntime.Phase.READY&&!plugin.getConfig().getBoolean("verification-enabled")&&economy.peers!=null,"normal_economy_connects_peer_flow_without_verification_runtime");
        return on(economy.stopTicker(),owner).thenCompose(v->on(economy.store.account(a),owner)).thenAccept(row->check(plugin,account(row).equals(expected.getProperty("a")),"new_JVM_first_account_items_money_revision_preserved"))
            .thenCompose(v->on(economy.store.account(b),owner)).thenAccept(row->check(plugin,account(row).equals(expected.getProperty("b")),"new_JVM_second_account_items_money_revision_preserved"))
            .thenCompose(v->on(economy.store.peerReceipt(a,RECEIPT),owner)).thenAccept(row->check(plugin,row.isPresent()&&row.get().firstRevision()==1&&row.get().secondRevision()==1,"new_JVM_confirmed_pair_receipt_restored"))
            .thenCompose(v->on(economy.store.peerReceipt(economy.store.context(RAW,C),UNKNOWN),owner)).thenAccept(row->check(plugin,row.isPresent(),"new_JVM_unknown_result_receipt_remains_readable_without_retry"))
            .thenCompose(v->connect(economy,a,owner)).thenCompose(v->connect(economy,b,owner)).thenAccept(s->check(plugin,economy.sessions.playable(s),"normal_controlled_session_restores_economic_peer_inventory"))
            .thenCompose(v->{var source=new PGSimpleDataSource();source.setServerNames(new String[]{runtime.settings().dbHost()});source.setPortNumbers(new int[]{runtime.settings().dbPort()});source.setDatabaseName(runtime.settings().dbName());source.setUser(runtime.settings().dbUser());source.setPassword(System.getenv(runtime.settings().passwordEnvironment()));source.setConnectTimeout(2);source.setSocketTimeout(5);var read=PostgresProgressStore.forReadOnlyModules(source,new ServerProgressAccess(),f->{});return on(read.module("peer_story_preserved",EconomyRuntimeVerification::progress).whenComplete((x,e)->read.closeAsync()),owner);}).thenAccept(hash->check(plugin,hash.equals(expected.getProperty("story")),"normal_process_and_peer_restore_preserve_story_database"));
    }
}
